<script>(()=>{const form=document.currentScript.closest('form'),type=form.querySelector('.target-type'),panels=[...form.querySelectorAll('.target-panel')];const sync=()=>panels.forEach(panel=>{const active=panel.dataset.type===type.value,control=panel.querySelector('[data-target-control]');panel.hidden=!active;control.disabled=!active;control.name=active?'target':'';});type.addEventListener('change',sync);sync();})();</script>
